    "    const m = table[mod];\012"
    "    const lines = ['const __s = globalThis[Symbol.for(\"scriptc.shared\")];'];\012"
    "    const lateIn = current === null \077 null : entries.get(current);\012"
    "    m.exports.forEach((e, slot) => {\012"
    "      const name = JSON.stringify(e.name);\012"
    "      const local = `__e${slot}`;\012"
    "      const tdz = nativeHost.sharedGet(mod, slot, 0, TDZ) === TDZ;\012"
    "      if (tdz && lateIn !== null && lateIn.late.some(([a, b]) => a === mod && b === slot)) {\012"
    "        lines.push(`export { ${lateName(mod, slot)} as ${name} } from ${JSON.stringify(current)};`);\012"
    "      } else if (tdz) {\012"
    "        // Reached outside an island load (a lazy require): no entry can hold\012"
    "        // the dead zone; the binding reads undefined until its declaration\012"
    "        // runs (NOTES.md shortcut).\012"
    "        lines.push(`let ${local} = __s.late(${mod}, ${slot}, (v) => { ${local} = v; });`);\012"
    "        lines.push(`export { ${local} as ${name} };`);\012"
    "      } else if (e.kind === \"let\" || e.kind === \"var\") {\012"
    "        lines.push(`let ${local} = __s.bind(${mod}, ${slot}, (v) => { ${local} = v; });`);\012"
    "        lines.push(`export { ${local} as ${name} };`);\012"
    "      } else {\012"
    "        lines.push(`const ${local} = __s.get(${mod}, ${slot});`);\012"
    "        lines.push(`export { ${local} as ${name} };`);\012"
    "      }\012"
    "    });\012"
    "    return lines.join(\"\\n\");\012"
    "  }\012"
    "\012"
    "  function entrySource(url) {\012"
    "    const e = entries.get(url);\012"
    "    const lines = [`import ${JSON.stringify(e.target)};`];\012"
    "    lines.push('const __s = globalThis[Symbol.for(\"scriptc.shared\")];');\012"
    "    for (const [mod, slot] of e.late) {\012"
    "      const n = lateName(mod, slot);\012"
    "      lines.push(`export let ${n} = __s.late(${mod}, ${slot}, (v) => { ${n} = v; });`);\012"
    "    }\012"
    "    return lines.join(\"\\n\");\012"
    "  }\012"
    "\012"
    "  registerHooks({\012"
    "    resolve(specifier, context, nextResolve) {\012"
    "      const asUrl = specifier.startsWith(\"/\") \077 pathToFileURL(specifier).href : specifier;\012"
    "      if (entries.has(asUrl)) return { url: asUrl, shortCircuit: true };\012"
    "      const resolved = nextResolve(specifier, context);\012"
    "      // A shared module keeps its own file URL (require() and import key\012"
    "      // their module records alike only for file URLs); load answers it.\012"
    "      if (resolved.url.startsWith(\"file:\") && byUrl.has(resolved.url))\012"
    "        return { url: resolved.url, format: \"module\", shortCircuit: true };\012"
    "      return resolved;\012"
    "    },\012"
    "    load(url, context, nextLoad) {\012"
    "      const mod = byUrl.get(url);\012"
    "      if (mod !== undefined)\012"
    "        return { format: \"module\", source: sharedSource(mod), shortCircuit: true };\012"
    "      if (entries.has(url))\012"
    "        return { format: \"module\", source: entrySource(url), shortCircuit: true };\012"
    "      return nextLoad(url, context);\012"
    "    },\012"
    "  });\012"
    "\012"
    "  return {\012"
    "    /** The entry to load the island module at `path` through, or null when\012"
    "     * no shared binding is in its temporal dead zone. Run `load` with it. */\012"
    "    entry(path, load) {\012"
    "      const late = JSON.parse(nativeHost.sharedTdz());\012"
    "      if (late.length === 0) return load(null);\012"
    "      // A file URL beside the island module (never on disk: the load hook\012"
    "      // answers it), so require() and import key it alike.\012"
    "      const url = pathToFileURL(join(dirname(path), `__scriptc_entry_${++entrySeq}.mjs`)).href;\012"
    "      entries.set(url, { target: pathToFileURL(path).href, late });\012"
    "      const outer = current;\012"
    "      current = url;\012"
    "      try {\012"
    "        return load(fileURLToPath(url));\012"
    "      } finally {\012"
    "        current = outer;\012"
    "      }\012"
    "    },\012"
    "    push(mod, slot, value) {\012"
    "      for (const set of setters.get(`${mod}:${slot}`) \077\077 []) set(value);\012"
    "    },\012"
    "  };\012"
    "}\012";

#endif /* SCR_NODE_ISLAND_HOST_H */
